package no.nibio.vips.util;

import java.io.BufferedInputStream;
import java.io.IOException;
import junit.framework.TestCase;

/**
 *
 * @author treinar
 */
public class ModelUtilTest extends TestCase {
    
    public ModelUtilTest(String testName) {
        super(testName);
    }
    
    @Override
    protected void setUp() throws Exception {
        super.setUp();
    }
    
    @Override
    protected void tearDown() throws Exception {
        super.tearDown();
    }

    /**
     * Test of getTextWithBase64EncodedImages method, of class ModelUtil.
     */
    public void testGetTextWithBase64EncodedImages() {
        try
        {
            System.out.println("getTextWithBase64EncodedImages");
            //String text = "Blablabla {{filename=\"/images/Epleskurv2.jpg\" description=\"Figur 2.4. Livssyklusen til a) sommerettårige, b) vinterettårige og c) toårige ugrasarter. Se tilsvarende\n figur for flerårige ugras i figur 2.8. " +
    //"Tegning: Hermod Karlsen.\" float=\"none\"}} oioioioioioio {{filename=\"/images/arch_themodel.png\" description=\"Figur 2.4\" float=\"left\"}} hohohohoh";
    String text = "Blablabla {{ description=\"Figur 2.4. Livssyklusen til a) sommerettårige, b) vinterettårige og c) toårige ugrasarter. Se tilsvarende\n figur for flerårige ugras i figur 2.8. " +
    "Tegning: Hermod Karlsen.\" float=\"none\"}} oioioioioioio {{filename=\"/images/arch_themodel.png\" description=\"Figur 2.4\" float=\"left\"}} hohohohoh";
            ModelUtil instance = new ModelUtil();
            String result = instance.getTextWithBase64EncodedImages(text, null);
            //System.out.println(result);
            assertNotNull(result);
        }
        catch(IOException ex)
        {
            fail(ex.getMessage());
        }
        
    }

    /**
     * Test of getBase64EncodedImage method, of class ModelUtil.
     */
    public void testGetBase64EncodedImage_InputStream() throws Exception {
        System.out.println("getBase64EncodedImage_inputStream");
        BufferedInputStream inputStream = new BufferedInputStream(this.getClass().getResourceAsStream("/images/arch_themodel.png"));
        
        ModelUtil instance = new ModelUtil();
        String expResult = "";
        String result = instance.getBase64EncodedImage(inputStream);
        //System.out.println(result);
        assertEquals(expResult, result);
        
    }

    
    
}
